            8 => ['The Hidden Fear', 'escalation', 'Beneath the ritualistic rules lies an overwhelming dread of accidental harm to loved ones.', 'Librarian Veda', 'Aggressive and taboo intrusive thoughts in OCD are ego-dystonic, contrasting sharply with psychotic impulses.', 'Ego-dystonic nature of OCD obsessions vs. ego-syntonic impulse disorders.'],
            9 => ['The Hat', 'revelation', 'The Unending Ritual manifests as a porcelain-masked specter adorned with clockwork gears.', 'The Unending Ritual', 'One flaw destroys the whole! Repeat the chant! Check the gate! Do not dare to leave the circle!', 'Differential diagnosis: OCD vs. OCPD (personality trait vs. symptomatic distress) and tic-related specifiers.'],
            10 => ['The Breaking Point', 'trial', 'The grand library lectern awaits the diagnostic solution that will break the compulsive cycle.', 'Scholar Julian', 'Prove your mastery over Obsessive-Compulsive and Related Disorders to free the academy!', 'Comprehensive chapter mastery challenge across all OCRD categories.'],
        ]);

        $c7 = self::buildChapterParts(7, 'Trauma-, Stressor-Related and Dissociative Disorders', 'The Shattered Self', [
            1 => ['The Ruined House', 'discovery', 'A burned estate where phantom flames flicker without generating heat.', 'Refugee Elena', 'Trauma- and Stressor-Related Disorders require exposure to a traumatic or stressful event as an indispensable Criterion A.', 'Criterion A for PTSD: exposure to actual or threatened death, serious injury, or sexual violence.'],
            2 => ['The Memory Room', 'discovery', 'Inside the parlor, the event replays in vivid, terrifying detail upon the walls.', 'Refugee Elena', 'Intrusion symptoms: distressing memories, nightmares, dissociative reactions (flashbacks), and psychological distress.', 'Intrusion symptoms (Criterion B) in PTSD.'],
            3 => ['The Sound', 'discovery', 'A loud crack of stone causes everyone in the courtyard to drop to the ground in panic.', 'Soldier Marcus', 'Hyperarousal: irritable behavior, reckless/destructive behavior, hypervigilance, exaggerated startle, and sleep disturbance.', 'Alterations in arousal and reactivity (Criterion E) in PTSD.'],
            4 => ['The Escape', 'investigation', 'Barricades block roads that remind travelers of the war, forcing them into desolate detours.', 'Soldier Marcus', 'Avoidance (Criterion C): persistent avoidance of distressing memories/thoughts/feelings or external reminders.', 'Avoidance criteria (Criterion C) in PTSD.'],
            5 => ['The Broken Mirror', 'investigation', 'A mirror reflects two distinct people who share the same clothing but have no memory of each other.', 'Refugee Elena', 'Dissociative Identity Disorder: disruption of identity characterized by 2+ distinct personality states and recurrent amnesia.', 'DID criteria: 2+ distinct personality states, amnesia, and possession-form presentations.'],
            6 => ['The Missing Day', 'investigation', 'A traveller awakens on a stone bench leagues from his home, unable to recall his voyage.', 'Refugee Elena', 'Dissociative Amnesia with Dissociative Fugue: inability to recall important autobiographical information, usually traumatic.', 'Dissociative Amnesia and Dissociative Fugue specifier.'],
            7 => ['The Shadows', 'escalation', 'Looking at their hands, travelers report feeling like automated puppets detached from their bodies.', 'Soldier Marcus', 'Depersonalization (detachment from one’s mind/body) and Derealization (detachment from one’s surroundings).', 'Depersonalization/Derealization Disorder and PTSD dissociative specifier.'],
            8 => ['The Split', 'escalation', 'An infant in an abandoned nursery flinches from caregivers, showing neither seeking nor response to comfort.', 'Refugee Elena', 'Reactive Attachment Disorder (RAD) and Disinhibited Social Engagement Disorder (DSED): patterns of extreme neglect.', 'RAD vs. DSED criteria in early childhood following severe social neglect.'],
            9 => ['The Shattered Self', 'revelation', 'The Shattered Self appears, alternating between multiple personas and reliving the fracture storm.', 'The Shattered Self', 'Do not assemble the pieces! When we are broken, the fire cannot find all of us at once!', 'Acute Stress Disorder (3 days to 1 month) vs. PTSD (>1 month) duration differentials.'],
            10 => ['The Memory Trial', 'trial', 'The amphitheater dais glows with the unified light of memory re-integration.', 'Soldier Marcus', 'Show complete diagnostic command of Trauma and Dissociative pathologies to restore the realm!', 'Comprehensive chapter mastery challenge across Trauma and Dissociative Disorders.'],
        ]);

        $c8 = self::buildChapterParts(8, 'Somatic Symptom and Related Disorders', 'The Body That Speaks', [
            1 => ['The Silent Clinic', 'discovery', 'An apothecary where patients arrive with genuine distress over physical complaints.', 'Doctor Paul', 'Somatic Symptom Disorder: distressing somatic symptoms accompanied by excessive thoughts, feelings, and behaviors.', 'Somatic Symptom Disorder: Criterion A (symptoms) and Criterion B (excessive thoughts/feelings/behaviors).'],
            2 => ['The Pulse', 'discovery', 'A patient checks his pulse every three minutes, convinced a minor variation signifies fatal failure.', 'Doctor Paul', 'The symptoms are not faked—the distress and impairment are clinically authentic and profound.', 'Authenticity of distress in SSD vs. malingering/factitious disorder.'],
            3 => ['The Pain Bell', 'discovery', 'A cathedral bell chimes with each report of persistent localized pain across the district.', 'Sister Teresa', 'With Predominant Pain specifier: assigned when somatic symptoms primarily involve pain.', 'SSD with Predominant Pain specifier and persistent course (>6 months).'],
            4 => ['The Mirror Body', 'investigation', 'A hall where people with no physical symptoms scour medical scrolls, convinced they harbor illness.', 'Sister Teresa', 'Illness Anxiety Disorder: preoccupation with having or acquiring a serious illness; somatic symptoms are absent or mild.', 'Illness Anxiety Disorder vs. Somatic Symptom Disorder (care-seeking vs. care-avoidant types).'],
            5 => ['The Physician\'s Archive', 'investigation', 'A knight suddenly loses the ability to move his sword arm after a traumatic duel, with no nerve damage.', 'Doctor Paul', 'Conversion Disorder (Functional Neurological Symptom Disorder): altered voluntary motor or sensory function incompatible with anatomy.', 'Conversion Disorder criteria: clinical findings provide evidence of incompatibility with neurological conditions.'],
            6 => ['The Unanswered Signal', 'investigation', 'Examination reveals "La belle indifférence" or Hoover\'s sign demonstrating genuine psychogenic etiology.', 'Doctor Paul', 'Neurological compatibility testing: Hoover\'s sign for leg paralysis and tubular visual fields in conversion.', 'Diagnostic clinical signs in Conversion Disorder evaluation.'],
            7 => ['The Cathedral of Symptoms', 'escalation', 'A wing of the clinic reveals patients intentionally faking symptoms to assume the sick role.', 'Sister Teresa', 'Factitious Disorder (Munchausen): falsification of medical signs/symptoms associated with identified deception without external reward.', 'Factitious Disorder imposed on self vs. imposed on another (by proxy).'],
            8 => ['The Voice Beneath', 'escalation', 'A merchant feigns paralysis solely to avoid military conscription and collect imperial gold.', 'Doctor Paul', 'Malingering: intentional production of false or exaggerated symptoms motivated by external incentives (not a mental disorder).', 'Malingering vs. Factitious Disorder (external incentives vs. assuming the sick role).'],
            9 => ['The Body That Speaks', 'revelation', 'The colossal stone golem rises from the clinic floor, pulsing with visceral energy.', 'The Body That Speaks', 'Hear the body! When the mind is silenced, the flesh must carry the grief!', 'Differential diagnosis across Somatic Symptom, Conversion, Illness Anxiety, and medical conditions.'],
            10 => ['The Integration Trial', 'trial', 'The clinic’s anatomical altar awaits the diagnostic mastery that will bridge mind and body.', 'Doctor Paul', 'Master the boundaries of Somatic Symptom and Related Disorders to heal the sanctuary!', 'Comprehensive chapter mastery challenge across Somatic Symptom and Related Disorders.'],
        ]);

        $c9 = self::buildChapterParts(9, 'Feeding, Eating, and Elimination Disorders', 'The Forbidden Appetite', [
            1 => ['The Banquet Hall', 'discovery', 'A grand hall loaded with roast meats and fresh bread, surrounded by starving courtiers.', 'Courtier Lucian', 'Feeding and Eating Disorders involve persistent disturbances in eating behaviors that impair physical health.', 'Overview of Feeding and Eating Disorders under DSM-5.'],
            2 => ['The Empty Table', 'discovery', 'A young noblewoman weighs a single leaf of lettuce, terrified of gaining weight despite severe emaciation.', 'Courtier Lucian', 'Anorexia Nervosa: restriction of energy intake leading to significantly low body weight, intense fear of gaining weight.', 'Anorexia Nervosa: Criteria A (low weight), B (fear of weight gain), and C (body image disturbance).'],
            3 => ['The Book of Rules', 'discovery', 'The imperial scale categorizes severity by Body Mass Index tiers.', 'Physician Gisele', 'Severity in Anorexia is based on BMI: Mild (>=17), Moderate (16-16.99), Severe (15-15.99), Extreme (<15).', 'Anorexia Nervosa BMI severity specifiers.'],
            4 => ['More', 'investigation', 'A table where restricting courtiers consume nothing, while others purge after brief meals.', 'Physician Gisele', 'Subtypes of Anorexia: Restricting type vs. Binge-eating/purging type over the preceding 3 months.', 'Anorexia Nervosa subtypes: Restricting vs. Binge-eating/purging.'],
            5 => ['Less', 'investigation', 'In the shadows, an individual consumes vast quantities of food in secret, followed by forced vomiting.', 'Courtier Lucian', 'Bulimia Nervosa: recurrent episodes of binge eating followed by inappropriate compensatory behaviors (at least 1x/week for 3 months).', 'Bulimia Nervosa criteria and differentiation from Anorexia (normal weight vs. underweight).'],
            6 => ['The Perfect Body', 'investigation', 'A courtyard where courtiers binge uncontrollably without compensatory purging, feeling disgust and guilt.', 'Physician Gisele', 'Binge-Eating Disorder (BED): recurrent binge eating without compensatory behaviors, associated with marked distress.', 'Binge-Eating Disorder criteria, features (eating rapidly, alone, until uncomfortably full), and absence of purging.'],
            7 => ['The Prison of Rules', 'investigation', 'A nursery where a toddler refuses food solely due to sensory texture, resulting in nutritional failure.', 'Physician Gisele', 'Avoidant/Restrictive Food Intake Disorder (ARFID): nutritional failure without distortion of body image or fear of weight gain.', 'ARFID vs. Anorexia Nervosa: absence of weight/shape concern.'],
            8 => ['The Forbidden Page', 'escalation', 'A pavilion where children repeatedly void urine into bed and clothing beyond the developmental age.', 'Courtier Lucian', 'Enuresis (involuntary/intentional voiding of urine, chronological age >= 5) and Encopresis (feces, age >= 4).', 'Elimination Disorders: Enuresis (age 5+) and Encopresis (age 4+) criteria and subtypes.'],
            9 => ['The Hunger', 'revelation', 'The Forbidden Appetite appears, clutching a massive scale and an iron lock.', 'The Forbidden Appetite', 'The scale never lies! Deny the flesh and achieve perfection, or be weighed and found lacking!', 'Medical complications of starvation, refeeding syndrome, and electrolyte imbalances in purging.'],
            10 => ['The Final Recipe', 'trial', 'The golden banquet table illuminates with the final diagnostic challenge.', 'Physician Gisele', 'Synthesize all diagnostic criteria for Feeding, Eating, and Elimination Disorders to restore the banquet!', 'Comprehensive chapter mastery challenge across Feeding, Eating, and Elimination Disorders.'],
        ]);

        $c10 = self::buildChapterParts(10, 'Sleep-Wake, Sexual Dysfunctions, and Gender Dysphoria', 'The Dreamer', [
            1 => ['The Sleeping City', 'discovery', 'A city submerged in twilight where half the citizens wander sleeplessly through dark lanes.', 'Oneiromancer Kael', 'Sleep-Wake Disorders involve dissatisfaction regarding the quality, timing, and amount of sleep resulting in daytime distress.', 'Overview of Sleep-Wake architecture and Insomnia Disorder criteria (3+ nights/week for 3+ months).'],
            2 => ['The Endless Night', 'discovery', 'A traveller suddenly collapses into REM sleep with loss of muscle tone during sudden emotion.', 'Oneiromancer Kael', 'Narcolepsy: recurrent irrepressible need to sleep accompanied by cataplexy (sudden bilateral loss of muscle tone) or hypocretin deficiency.', 'Narcolepsy criteria, cataplexy mechanisms, and hypocretin/orexin deficiency.'],
            3 => ['The Dream Corridor', 'discovery', 'Sleepwalkers navigate dangerous ledges during slow-wave sleep without awakening or memory.', 'Oneiromancer Kael', 'Non-REM Sleep Arousal Disorders: sleepwalking and sleep terrors occurring during NREM slow-wave sleep with amnesia.', 'Non-REM Sleep Arousal Disorders vs. Nightmare Disorder (REM vs. NREM).'],
            4 => ['The Mirror Self', 'investigation', 'Reflecting pools where lovers look upon their intimacy with persistent, distressing inhibition.', 'Mistress Talia', 'Sexual Dysfunctions require a minimum duration of approximately 6 months and cause clinically significant distress.', 'General criteria for Sexual Dysfunctions under DSM-5 (6-month rule, distress threshold).'],
            5 => ['The Unfamiliar Body', 'investigation', 'A male courtier experiences persistent inability to achieve or maintain an erection during intimacy.', 'Mistress Talia', 'Erectile Disorder, Delayed Ejaculation, and Premature (Early) Ejaculation: duration, severity, and context specifiers.', 'Male sexual dysfunctions: criteria, lifelong vs. acquired, generalized vs. situational.'],
            6 => ['The Silent Theatre', 'investigation', 'A sanctuary where female voyagers report persistent lack of sexual interest and pelvic pain during intercourse.', 'Mistress Talia', 'Female Sexual Interest/Arousal Disorder and Genito-Pelvic Pain/Penetration Disorder under DSM-5 taxonomy.', 'Female sexual dysfunctions and pain disorders.'],
            7 => ['The Winged Dreamer', 'investigation', 'A youth gazes into a moonlit fountain, experiencing profound discordance with their assigned birth gender.', 'Oneiromancer Kael', 'Gender Dysphoria in Children: marked incongruence between experienced/expressed gender and assigned gender for >= 6 months.', 'Gender Dysphoria in Children: 6 of 8 criteria including strong desire to be of the other gender.'],
            8 => ['The Broken Dream', 'escalation', 'An adolescent recounts the agonizing distress of developing secondary sex characteristics inconsistent with identity.', 'Oneiromancer Kael', 'Gender Dysphoria in Adolescents and Adults: 2 of 6 criteria accompanied by clinically significant distress or impairment.', 'Gender Dysphoria in Adolescents and Adults criteria and post-transition specifier.'],
            9 => ['The Awakening', 'revelation', 'The Dreamer descends from the lavender sky on wings of slumbering mist and starlight.', 'The Dreamer', 'Dream and waking, body and soul... the Fracture has turned the mirror into a cage! Yield to the endless night!', 'Distinguishing Gender Dysphoria from Transvestic Disorder and cultural nonconformity.'],
            10 => ['The Lucid Trial', 'trial', 'The nocturnal pavilion illuminates with the radiant runes of diagnostic synthesis.', 'Mistress Talia', 'Demonstrate complete clinical mastery across Sleep, Sexual, and Gender Incongruence criteria!', 'Comprehensive chapter mastery challenge across Chapter 10 domains.'],
        ]);

        $c11 = self::buildChapterParts(11, 'Substance-Related, Addictive, and Disruptive Disorders', 'The Hungering Mind', [
            1 => ['The Golden Market', 'discovery', 'A bustling bazaar where merchants peddle elixirs promising instant euphoria and boundless vitality.', 'Merchant Silas', 'Substance Use Disorders involve a cluster of cognitive, behavioral, and physiological symptoms across 11 criteria.', 'The 11 core DSM-5 SUD criteria across impaired control, social impairment, risky use, and pharmacological indicators.'],
            2 => ['The First Reward', 'discovery', 'A patron drinks from a golden goblet, immediately seeking a second, larger cup to achieve the same surge.', 'Merchant Silas', 'Tolerance: a need for markedly increased amounts of substance to achieve intoxication or desired effect.', 'Pharmacological criteria: Tolerance and Withdrawal definitions under DSM-5.'],
            3 => ['The Shortcut', 'discovery', 'Citizens spend their life savings on dice games, chasing losses with frantic determination.', 'Gambler Jax', 'Gambling Disorder: persistent and recurrent problematic gambling behavior (4 of 9 criteria) leading to clinically significant impairment.', 'Gambling Disorder as the sole non-substance behavioral addiction in DSM-5.'],
            4 => ['The Cost', 'investigation', 'A tavern where shaking patrons experience severe tremors, sweating, and hallucinations after alcohol stops.', 'Merchant Silas', 'Alcohol Withdrawal: autonomic hyperactivity, hand tremor, insomnia, hallucinations, psychomotor agitation, and seizures.', 'Alcohol-Related Disorders: intoxication, withdrawal, and Delirium Tremens.'],
            5 => ['The Chase', 'investigation', 'A cold alleyway where an adventurer suffers pinpoint pupils, shallow respiration, and coma.', 'Physician Thorne', 'Opioid Intoxication: pupillary constriction (miosis), drowsiness, slurred speech, and fatal respiratory depression.', 'Opioid Use Disorder: overdose recognition, naloxone mechanisms, and withdrawal symptoms.'],
            6 => ['The Cage', 'investigation', 'In the lower market, a youth repeatedly defies town elders, arguing furiously and blaming others for his errors.', 'Bailiff Orson', 'Oppositional Defiant Disorder (ODD): pattern of angry/irritable mood, argumentative/defiant behavior, or vindictiveness for >= 6 months.', 'ODD criteria: 4 symptoms across angry/irritable mood, argumentative/defiant behavior, and vindictiveness.'],
            7 => ['The Purple Mind', 'investigation', 'A teenager sets fire to a granary and tortures stray animals without displaying empathy or remorse.', 'Bailiff Orson', 'Conduct Disorder: repetitive and persistent pattern of behavior violating the basic rights of others or societal norms (3 of 15 criteria).', 'Conduct Disorder criteria: aggression to people/animals, destruction of property, deceitfulness/theft, serious rule violations.'],
            8 => ['The Deal', 'escalation', 'A merchant burns his own warehouse solely to witness the blaze, feeling intense arousal prior to ignition.', 'Bailiff Orson', 'Pyromania: deliberate and purposeful fire setting on more than one occasion, accompanied by tension/arousal prior to act.', 'Impulse-Control Disorders: Pyromania and Kleptomania criteria and distinctions.'],
            9 => ['The Hunger', 'revelation', 'The Hungering Mind coils around the golden bazaar, radiating insatiable craving and dopaminergic fury.', 'The Hungering Mind', 'More! It is never enough! The shortcut is open, and all of you will burn to feed my reward circuit!', 'Differential diagnosis: SUD vs. substance-induced disorders, Conduct Disorder with limited prosocial emotions, and ODD progression.'],
            10 => ['The Choice Trial', 'trial', 'The market’s central fountain awaits the diagnostic resolution of addiction and conduct pathology.', 'Merchant Silas', 'Prove your diagnostic precision across Substance-Related and Disruptive Disorders to break the cycle!', 'Comprehensive chapter mastery challenge across Chapter 11 domains.'],
        ]);

        $c12 = self::buildChapterParts(12, 'Neurocognitive, Personality, and Paraphilic Disorders', 'The Mask of a Thousand Selves', [
            1 => ['The Palace', 'discovery', 'You step into the imperial palace where ancestral chronicles are unweaving into blank parchment.', 'Chancellor Morgan', 'Neurocognitive Disorders involve clinically significant deficits in cognitive function representing a decline from baseline.', 'Overview of Neurocognitive Disorders: Delirium, Major NCD, and Mild NCD across 6 cognitive domains.'],
            2 => ['The First Mask', 'discovery', 'An elderly courtier fluctuates hourly between lucid speech and acute confusion, unable to focus his attention.', 'Chancellor Morgan', 'Delirium: disturbance in attention and awareness developing over a short period of time (hours to days), fluctuating in severity.', 'Delirium criteria: acute onset, fluctuating course, disturbance in attention/orientation, and underlying medical etiology.'],
            3 => ['The Mirror Hall', 'discovery', 'Grand courtiers navigate the halls wearing rigid porcelain masks representing immutable character styles.', 'Mask-Maker Kira', 'Personality Disorders: an enduring pattern of inner experience and behavior deviating markedly from cultural expectations.', 'General Personality Disorder criteria under DSM-5 (pervasive, inflexible, stable across time, onset by adolescence/early adulthood).'],
            4 => ['The Forgotten Room', 'investigation', 'A scholar forgets the names of his own children and cannot manage his imperial ledgers without total assistance.', 'Chancellor Morgan', 'Major Neurocognitive Disorder: significant cognitive decline interfering with independence in everyday activities.', 'Major vs. Mild NCD distinction: independence in instrumental activities of daily living (IADLs).'],
            5 => ['The Fading Archive', 'investigation', 'Courtiers display paranoia in Cluster A, dramatic instability in Cluster B, and anxious inhibition in Cluster C.', 'Mask-Maker Kira', 'Cluster A (Odd/Eccentric: Paranoid, Schizoid, Schizotypal), Cluster B (Dramatic: Antisocial, Borderline, Histrionic, Narcissistic), Cluster C (Anxious: Avoidant, Dependent, OCPD).', 'The three Personality Disorder clusters and hallmark presentations.'],
            6 => ['The Thousand Faces', 'investigation', 'A courtier with Borderline Pathology swings between extreme idealization and devaluation, terrified of abandonment.', 'Mask-Maker Kira', 'Borderline Personality Disorder: pattern of instability of interpersonal relationships, self-image, affects, and marked impulsivity.', 'BPD criteria: 5 of 9 symptoms including frantic efforts to avoid abandonment, splitting, and recurrent self-harm.'],
            7 => ['The Forbidden Wing', 'investigation', 'In a restricted gallery, atypical sexual arousal patterns are preserved behind velvet curtains.', 'Chancellor Morgan', 'Paraphilia vs. Paraphilic Disorder: a paraphilia is not a disorder unless it causes distress, impairment, or harm to nonconsenting others.', 'Criterion A (arousal focus) vs. Criterion B (distress, impairment, harm) in Paraphilic Disorders.'],
            8 => ['The Truth', 'escalation', 'Chronicles reveal that The Creator tried to force every nuance of identity into twelve rigid, mechanical cages.', 'Chancellor Morgan', 'The Creator’s attempt to eradicate human cognitive complexity caused the Fracture! The guardians were forced to enforce impossible boundaries.', 'Diagnostic synthesis across Neurocognitive decline, Character pathology, and Paraphilic forensic boundaries.'],
            9 => ['The Creator\'s Seal', 'revelation', 'The Mask of a Thousand Selves rises above the imperial throne, wearing the obsidian seal of the Creator.', 'The Mask of a Thousand Selves', 'I am the final boundary! If you unseat me, the Black Archive will open, and the Creator will test your very existence!', 'Complex licensure vignettes differentiating Alzheimer\'s, Frontotemporal NCD, Lewy Body NCD, and Cluster A-C disorders.'],
            10 => ['The Final Archive', 'trial', 'The grand imperial altar glows with the ultimate synthesis of psychiatric knowledge.', 'Mask-Maker Kira', 'Conquer this final trial, unite all twelve Mind Seals, and reveal the road to the Black Archive!', 'Chapter 12 Climax Mastery Challenge preparing the Mindkeeper for the ultimate Creator confrontation.'],
        ]);

        return array_merge($c1, $c2, $c3, $c4, $c5, $c6, $c7, $c8, $c9, $c10, $c11, $c12);
    }

    private static function buildChapterParts(int $chId, string $domainTitle, string $bossName, array $partDefs): array {
        $result = [];
        foreach ($partDefs as $num => $p) {
            $result[($chId - 1) * 10 + $num] = [
                'chapter_id' => $chId,
                'part_number' => $num,
                'story_title' => $p[0],
                'phase' => $p[1],
                'intro' => $p[2],
                'speaker' => $p[3],
                'dialogue' => $p[4],
                'academic' => $p[5],
                'enemy' => "Echo of " . $p[0],
                'flavor' => "A corrupted distortion of the {$p[0]} testing the Mindkeeper's knowledge.",
                'after' => "The anomaly recedes into harmonious clarity. The chapter story advances toward {$bossName}.",
            ];
        }
        return $result;
    }
}
